using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline pages with a deep Skip/Take; Optimized calls the agent-owned
// KeysetPaginationSolution.Run. Do not edit this file — edit
// Scenarios/KeysetPagination.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class KeysetPaginationBenchmark
{
    private const int AfterId = 80000;
    private const int PageSize = 20;
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedOrders(db, orders: 100000);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), o => o.Id.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<OrderRow> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        return db.Orders
            .OrderBy(o => o.Id)
            .Skip(AfterId)
            .Take(PageSize)
            .Select(o => new OrderRow(o.Id, o.CreatedAt, o.Total))
            .ToList();
    }

    [Benchmark]
    public List<OrderRow> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return KeysetPaginationSolution.Run(db, AfterId, PageSize);
    }
}
